6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1856,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 6.16\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T769,"])self.__next_f.push([1,"Regulation of diet and sleep is recommended herein for the yogīs. Too much eating means eating more than is required to keep the body and soul together. There is no need for men to eat animals, because there is an ample supply of grains, vegetables, fruits and milk. Such simple foodstuff is considered to be in the mode of goodness according to the Bhagavad-gītā. Animal food is for those in the mode of ignorance. Therefore, those who indulge in animal food, drinking, smoking and eating food which is not first offered to Kṛṣṇa will suffer sinful reactions because of eating only polluted things. Bhuñjate te tv aghaṁ pāpā ye pacanty ātma-kāraṇāt. Anyone who eats for sense pleasure, or cooks for himself, not offering his food to Kṛṣṇa, eats only sin. One who eats sin and eats more than is allotted to him cannot execute perfect yoga. It is best that one eat only the remnants of foodstuff offered to Kṛṣṇa. A person in Kṛṣṇa consciousness does not eat anything which is not first offered to Kṛṣṇa. Therefore, only the Kṛṣṇa conscious person can attain perfection in yoga practice. Nor can one who artificially abstains from eating, manufacturing his own personal process of fasting, practice yoga. The Kṛṣṇa conscious person observes fasting as it is recommended in the scriptures. He does not fast or eat more than is required, and he is thus competent to perform yoga practice. One who eats more than required will dream very much while sleeping, and he must consequently sleep more than is required. One should not sleep more than six hours daily. One who sleeps more than six hours out of twenty-four is certainly influenced by the mode of ignorance. A person in the mode of ignorance is lazy and prone to sleep a great deal. Such a person cannot perform yoga."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1856,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"16\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 16\",\"advanced_view_url_path\":\"/en/library/bg/6/advanced-view/#bb1642\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/6/16/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/6/16/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/6/16/\"},{\"display_n