nks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1885,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 6.20-23\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T6d1,"])self.__next_f.push([1,"yatra – in that state of affairs where; uparamate – cease (because one feels transcendental happiness); cittam – mental activities; niruddham – being restrained from matter; yoga-sevayā – by performance of yoga; yatra – in which; ca – also; eva – certainly; ātmanā – by the pure mind; ātmānam – the Self; paśyan – realizing the position of; ātmani – in the Self; tuṣyati – one becomes satisfied; sukham – happiness; ātyantikam – supreme; yat – which; tat – that; buddhi – by intelligence; grāhyam – accessible; atīndriyam – transcendental; vetti – one knows; yatra – wherein; na – never; ca – also; eva – certainly; ayam – he; sthitaḥ – situated; calati – moves; tattvataḥ – from the truth; yam – that which; labdhvā – by attainment; ca – also; aparam – any other; lābham – gain; manyate – considers; na – never; adhikam – more; tataḥ – than that; yasmin – in which; sthitaḥ – being situated; na – never; duḥkhena – by miseries; guruṇā api – even though very difficult; vicālyate – becomes shaken; tam – that; vidyāt – you must know; duḥkha-saṁyoga – of the miseries of material contact; viyogam – extermination; yoga-saṁjñitam – called trance in yoga."])self.__next_f.push([1,"26:T544,By practice of yoga one becomes gradually detached from material concepts. This is the primary characteristic of the yoga principle. And after this, one becomes situated in trance, or samādhi, which means that the yogī realizes the Supersoul through transcendental mind and intelligence, without any of the misgivings of identifying the self with the Superself. Yoga practice is more or less based on the principles of the Patañjali system. Some unauthorized commentators try to identify the individual soul with the Supersoul, and the monists think this to be liberation, but they do not understand the real purpose of the Patañjali system of yoga. There is an acceptance of transcendental pleasure in the Patañjali system, but the monists do not accept this transcendental pleasure, out of fear of jeopardizing the theory of oneness. The duality of knowledge and knower is not accepted by the nondualist, but in this verse transcendental pleasure – realized through transcendental senses – is accepted. And this is corroborated by Patañjali Muni, the famous exponent of the yoga system. The great sage declares in his Yoga-sūtras (4.33): puruṣārtha-śūnyānāṁ guṇānāṁ pratiprasavaḥ kaivalyaṁ svarūpa-pratiṣṭhā vā citi-śaktir iti.27:T51a,In the yoga system, as described in this chapter, there are two kinds of samādhi, called samprajñāta-samādhi and asamprajñāta-samādhi. When one becomes situated in the transcendental position by various philosophical researches, he is said to have achieved samprajñāta-samādhi. In the asamprajñāta-samādhi there is no longer any connection with mundane pleasure, for one is then transcendental to all sorts of happiness derived from the senses. When the yogī is once situated in that transcendental position, he is never shaken from it. Unless the yogī is able to reach this position, he is unsuccessful. Today’s so-called yoga practice, which involves various sense pleasures, is contradictory. A yogī indulging in sex and intoxication is a mockery. Even those yogīs who are attracted by the siddhis (perfections) in the process of yoga are not perfectly situated. If yogīs are attracted by the by-products of yoga, then they cannot attain the stage of perfection, as is stated in this verse. Persons, therefore, indulging in the make-show practice of gymnastic feats or siddhis should know that the aim of yoga is lost in that way."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1885,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"20-23\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 20-23\",\"advanced_view_url_path\":\"/en/library/bg/6/advanced-view/#bb1667\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/6/20-23/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/6/20-23/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/6/20-23/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/6/20-23/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_