e,\"url_path\":\"/uk/library/bg/6/20-23/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/6/\",\"title\":\"Chapter Six: Dhyāna-yoga\"}],\"url_path\":\"/en/library/bg/6/20-23/\",\"bb\":1667,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/6/19/\",\"title\":\"TEXT 19\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/6/24/\",\"title\":\"TEXT 24\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1886,\"bb\":568125,\"url_path\":\"/en/library/bg/6/20-23/devanagari/\",\"body_final\":\"यत्रोपरमते चित्तं निरुद्धं योगसेवया ।
यत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥ २० ॥
सुखमात्यन्तिकं यत्तद्‍बुद्धिग्राह्यमतीन्द्रियम् ।
वेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वत: ॥ २१ ॥
यं लब्ध्वा चापरं लाभं मन्यते नाधिकं तत: ।
यस्मिन्स्थितो न दु:खेन गुरुणापि विचाल्यते ॥ २२ ॥
तं विद्याद्दु:खसंयोगवियोगं योगसंज्ञितम् ॥ २३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1887,\"bb\":1668,\"url_path\":\"/en/library/bg/6/20-23/b1668/\",\"body_value\":\"yatroparamate cittaṁ
niruddhaṁ yoga-sevayā
yatra caivātmanātmānaṁ
paśyann ātmani tuṣyati\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1888,\"bb\":1669,\"url_path\":\"/en/library/bg/6/20-23/b1669/\",\"body_value\":\"sukham ātyantikaṁ yat tad
buddhi-grāhyam atīndriyam
vetti yatra na caivāyaṁ
sthitaś calati tattvataḥ\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1889,\"bb\":1670,\"url_path\":\"/en/library/bg/6/20-23/b1670/\",\"body_value\":\"yaṁ labdhvā cāparaṁ lābhaṁ
manyate nādhikaṁ tataḥ
